# Chatbook remote script prelude (protocol ACPR1). Generated by acpRemoteScript; placeholders for the nonce and deadline.
# Everything below the BEGIN marker on standard output is framed:
#   F <name> <exit|-> <outlen> <outtrunc> <errlen> <errtrunc>\n<out bytes><err bytes>\n
#   S <code>\n                      (the script stopped early; informational)
#   #ACPR1 <nonce> END\n            (the script ran to the end)
cb_nonce='@NONCE@'
LC_ALL=C
export LC_ALL
unset CDPATH
umask 077
set -f
# Only absolute PATH entries: an empty or relative entry (PATH=:/usr/bin, a trailing ":", ".") would run programs from
# the folder the script cd's into, e.g. a cloned repository's "uname" or "tr" during every automatic git check. The
# exported PATH also covers git's own children.
cb_path=
IFS=:
for cb_x in $PATH; do case $cb_x in /*) cb_path=${cb_path:+$cb_path:}$cb_x;; esac; done
unset IFS
PATH=${cb_path:-/usr/bin:/bin}
export PATH
cb_d=
cb_wd=
cb_cleanup() {
    if [ -n "$cb_wd" ]; then kill "$cb_wd" 2>/dev/null; fi
    if [ -n "$cb_d" ]; then rm -rf -- "$cb_d"; fi
}
trap 'cb_cleanup' EXIT
trap 'exit 129' HUP
trap 'exit 130' INT
trap 'exit 143' TERM
trap 'exit 141' PIPE
# Watchdog: after the deadline, the whole process group (sshd makes the remote shell a group leader) is terminated, so
# work whose local ssh was killed does not go on forever.
cb_watchdog() {
    trap 'kill "$cb_ws" 2>/dev/null; exit 0' TERM
    sleep "$1" &
    cb_ws=$!
    wait "$cb_ws"
    kill -s TERM 0
}
cb_watchdog '@DEADLINE@' </dev/null >/dev/null 2>&1 &
cb_wd=$!
printf '\n#ACPR1 %s BEGIN\n' "$cb_nonce"
cb_end() {
    printf '#ACPR1 %s END\n' "$cb_nonce"
    exit 0
}
cb_stop() {
    printf 'S %s\n' "$1"
    cb_end
}
cb_t=${TMPDIR:-/tmp}
cb_t=${cb_t%/}
cb_d=$(mktemp -d "$cb_t/chatbook.XXXXXX" 2>/dev/null) || cb_d=
# Only the directory mktemp made is ever written to or removed
case $cb_d in "$cb_t"/chatbook.??????) ;; *) cb_d=;; esac
if [ -z "$cb_d" ] || [ ! -d "$cb_d" ]; then cb_d=; cb_stop tmpdir; fi
# Size of a file in bytes (0 if it does not exist); wc pads with spaces on macOS
cb_size() {
    if [ -f "$1" ]; then cb_s1=$(wc -c < "$1") && cb_s1=$((cb_s1)) || cb_s1=0; else cb_s1=0; fi
    printf '%s' "$cb_s1"
}
# cb_emit name exit outfile errfile outcap errcap: one frame; the files are cut at the caps
cb_emit() {
    cb_ol=$(cb_size "$3"); cb_ot=0
    if [ "$cb_ol" -gt "$5" ]; then cb_ol=$5; cb_ot=1; fi
    cb_el=$(cb_size "$4"); cb_et=0
    if [ "$cb_el" -gt "$6" ]; then cb_el=$6; cb_et=1; fi
    printf 'F %s %s %s %s %s %s\n' "$1" "$2" "$cb_ol" "$cb_ot" "$cb_el" "$cb_et"
    if [ "$cb_ol" -gt 0 ]; then head -c "$cb_ol" < "$3"; fi
    if [ "$cb_el" -gt 0 ]; then head -c "$cb_el" < "$4"; fi
    printf '\n'
}
# cb_value name string: a frame with a value (no exit code)
cb_value() {
    printf '%s' "$2" > "$cb_d/v"
    cb_emit "$1" - "$cb_d/v" /dev/null 1048576 0
}
# cb_run name outcap errcap command args...: runs the command (standard input /dev/null, never the script) with its
# output cut at outcap+1 bytes (a command that writes more gets SIGPIPE, so it stops early), then emits its frame.
# Leaves the output in $cb_d/o and the exit code in $cb_rc.
cb_run() {
    cb_nm=$1; cb_oc=$2; cb_ec=$3
    shift 3
    : > "$cb_d/rc"
    { "$@" </dev/null 2>"$cb_d/e"; printf '%s' "$?" > "$cb_d/rc"; } | head -c "$((cb_oc + 1))" > "$cb_d/o"
    cb_rc=
    IFS= read -r cb_rc < "$cb_d/rc" || :
    case $cb_rc in ''|*[!0-9]*) cb_rc=255;; esac
    cb_emit "$cb_nm" "$cb_rc" "$cb_d/o" "$cb_d/e" "$cb_oc" "$cb_ec"
}
# cb_truncated outcap: whether the last cb_run's output was cut
cb_truncated() {
    [ "$(cb_size "$cb_d/o")" -gt "$1" ]
}
